import urllib.request
import urllib.error
import time
from typing import Optional

class RateLimitError(Exception):
    """Raised when rate limit is exceeded after retries."""
    pass

class ServerError(Exception):
    """Raised when a server error (5xx) occurs after retries."""
    pass

class ClientError(Exception):
    """Raised when a client error (4xx, except 429) occurs."""
    pass

class ConnectionError(Exception):
    """Raised when a network error occurs after retries."""
    pass

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10):
        self.base_url = base_url
        self.timeout = timeout

    def _make_request(self, path: str) -> str:
        url = f"{self.base_url}{path}"
        request = urllib.request.Request(url)

        # Retry logic wrapper
        max_retries = 0
        retry_delays = []

        # Determine retry strategy based on error type
        def get_retry_config(error: urllib.error.HTTPError) -> tuple[int, list[float]]:
            status = error.code
            if status == 429:
                # Rate limit: retry up to 3 times with exponential backoff (0.5, 1, 2)
                return 3, [0.5, 1.0, 2.0]
            elif 500 <= status < 600:
                # Server error: retry once after 1s
                return 1, [1.0]
            else:
                # Client error (4xx except 429): no retry
                return 0, []

        def get_retry_config_network(error: urllib.error.URLError) -> tuple[int, list[float]]:
            # Network error: retry once after 1s
            return 1, [1.0]

        def execute_with_retry():
            nonlocal max_retries, retry_delays

            while True:
                try:
                    with urllib.request.urlopen(url, timeout=self.timeout) as response:
                        return response.read().decode('utf-8')
                except urllib.error.HTTPError as e:
                    status = e.code
                    if status == 429:
                        if max_retries >= 3:
                            raise RateLimitError("Rate limit exceeded after retries")
                        max_retries += 1
                        delay = retry_delays[max_retries - 1]
                        time.sleep(delay)
                        continue
                    elif 500 <= status < 600:
                        if max_retries >= 1:
                            raise ServerError(f"Server error {status} after retry")
                        max_retries += 1
                        delay = retry_delays[max_retries - 1]
                        time.sleep(delay)
                        continue
                    else:
                        # 4xx (except 429)
                        raise ClientError(f"Client error {status}: {e.reason}")
                except urllib.error.URLError as e:
                    if max_retries >= 1:
                        raise ConnectionError(f"Network error after retry: {e.reason}")
                    max_retries += 1
                    delay = retry_delays[max_retries - 1]
                    time.sleep(delay)
                    continue

        # Initial attempt
        return execute_with_retry()

    def get(self, path: str) -> str:
        return self._make_request(path)
